import{createState,check,combatAction,record,clamp}from'./engine.js';
export const copy=x=>structuredClone(x);
export function companionId(s){return s.player==='jihyo'?'baekho':'jihyo'}
export function trustValue(s){return s.relations[companionId(s)+':'+s.player].trust}
export function newStory(world,player='jihyo',seed=Date.now()){
 const s=createState(world,player,seed);s.version=3;s.location='forest';s.visited=['forest'];s.day=1;s.tick=0;s.todayActions=0;s.log=[];s.serial=0;s.pending=null;s.combat=null;
 s.story={completed:[],mainDone:[],active:null,flags:[],pressure:30,route:null,routeReasons:[],ending:null,records:[],revision:0,sleepCount:0};
 record(s,'하얀 유성이 숲에 떨어졌다. 연기가 걷히고, 백호와 지효가 처음으로 마주친다. 이 산에서의 이야기는 아직 정해지지 않았다.','story',8);
 return s;
}
export function eligibleMain(s,plots){return plots.mains.find(p=>!s.story.mainDone.includes(p.id)&&s.story.completed.length>=p.threshold)||null}
export function currentPlot(s,plots){if(!s.story.active)return null;return [...plots.subs,...plots.mains].find(p=>p.id===s.story.active.plot)}
export function currentNode(s,plots){const p=currentPlot(s,plots);return p?.nodes.find(n=>n.id===s.story.active.node)}
export function locks(s,req={}){const reasons=[];for(const f of req.flags||[])if(!s.story.flags.includes(f))reasons.push('앞선 사건에서 얻는 단서 필요');if(req.anyFlags&&!req.anyFlags.some(f=>s.story.flags.includes(f)))reasons.push('관련 준비 또는 단서 필요');for(const[k,v]of Object.entries(req.stats||{}))if((s.characters[s.player][k]??0)<v)reasons.push(`${{energy:'기력',insight:'통찰',will:'의지',power:'힘'}[k]||k} ${v} 이상`);for(const[k,v]of Object.entries(req.items||{}))if((s.inventory[k]??0)<v)reasons.push(`${k==='herb'?'약초':k} ${v}개 필요`);if(req.trust&&trustValue(s)<req.trust)reasons.push(`상대의 신뢰 ${req.trust} 이상`);return reasons}
export function setupDecision(s,plots){if(s.story.ending)return null;if(s.pending)return s.pending;const main=eligibleMain(s,plots);if(!s.story.active&&main)s.story.active={plot:main.id,node:main.entry};const node=currentNode(s,plots);s.pending={id:`${s.seed}-${s.story.revision}`,turn:s.tick+1,day:s.day,kind:s.combat?'combat':node?'node':'menu',plot:s.story.active?.plot||null,node:node?.id||null};return s.pending}
export function chooseRoute(s){const f=s.story.flags;if(f.includes('false_report')&&s.story.pressure<55)return{route:'quiet',reasons:['거짓 보고로 추적 방향을 바꿨다.','남긴 위협이 크지 않았다.']};if(f.includes('parley')&&s.story.pressure<=30)return{route:'quiet',reasons:['협상 의사가 전해졌다.','추가 도발이 공격을 촉발하지 않았다.']};if(s.story.pressure>=60)return{route:'snake',reasons:['도발과 드러난 힘이 뱀의 직접 개입을 불렀다.']};return{route:'minions',reasons:['직접 개입할 만큼 위협적이지 않지만 추적은 멈추지 않았다.']}}
function applyEffects(s,e={}){const p=s.characters[s.player];for(const[k,v]of Object.entries(e.stats||{})){const max=k==='hp'?p.maxHp:k==='energy'?p.maxEnergy:100;p[k]=clamp((p[k]||0)+v,k==='hp'?1:0,max)}for(const[k,v]of Object.entries(e.items||{}))s.inventory[k]=Math.max(0,(s.inventory[k]||0)+v);s.story.pressure=clamp(s.story.pressure+(e.pressure||0));for(const f of e.flags||[])if(!s.story.flags.includes(f))s.story.flags.push(f);const r=s.relations[companionId(s)+':'+s.player];r.trust=clamp(r.trust+(e.trust||0));r.affection=clamp(r.affection+Math.max(0,Math.floor((e.trust||0)/2)))}
function finishNode(s,choice,plots){if(choice.ending){s.story.ending=choice.ending;s.story.mainDone.push(s.story.active.plot);s.story.active=null;return}if(choice.next==='@arrival'){const r=chooseRoute(s);s.story.route=r.route;s.story.routeReasons=r.reasons;s.story.active.node=r.route;return}if(choice.next&&choice.next!=='done'){s.story.active.node=choice.next;return}const p=currentPlot(s,plots);(p.kind==='sub'?s.story.completed:s.story.mainDone).push(p.id);s.story.active=null}
function statsForDiff(s){const p=s.characters[s.player];return{체력:p.hp,기력:p.energy,힘:p.power,민첩:p.agility,통찰:p.insight,의지:p.will,정신안정:p.stability,약초:s.inventory.herb,소지금:s.inventory.coins,신뢰:trustValue(s)}}
const battleActions=['attack','skill','guard','dodge','approach','retreat','environment','negotiate','flee','item'];
export function storyAction(s,input,plots,expectedId){if(!s.pending||s.pending.id!==expectedId||s.story.ending)return{ok:false,state:s,error:'이미 처리되었거나 종료된 선택입니다.'};const n=copy(s),logStart=n.log.length,dayBefore=n.day;let before=statsForDiff(n);let label,title,text='',roll=null,consume=true;
 if(input.type==='openSub'){if(n.pending.kind!=='menu'||!plots.subs.some(p=>p.id===input.id)||n.story.completed.includes(input.id)||eligibleMain(n,plots))return{ok:false,state:s,error:'지금 열 수 없는 사건입니다.'};const p=plots.subs.find(p=>p.id===input.id);n.story.active={plot:p.id,node:p.entry};n.pending=null;n.story.revision++;setupDecision(n,plots);return{ok:true,state:n,committed:false}}
 if(input.type==='back'){if(!n.story.active||currentPlot(n,plots).kind!=='sub'||n.combat)return{ok:false,state:s,error:'이 사건은 먼저 해결해야 합니다.'};n.story.active=null;n.pending=null;n.story.revision++;setupDecision(n,plots);return{ok:true,state:n,committed:false}}
 if(n.combat){if(input.type!=='battle'||!battleActions.includes(input.id))return{ok:false,state:s,error:'전투 행동을 선택하세요.'};const old=n.combat,ok=combatAction(n,input.id);if(!ok)return{ok:false,state:s,error:n.log.slice(logStart).find(e=>e.type==='system')?.text||'실행할 수 없는 전투 행동입니다.'};n.story.revision++;if(n.combat){n.pending=null;setupDecision(n,plots);return{ok:true,state:n,committed:false}}const resolution=n.story.battleContinuation;before=resolution.baseline;label=resolution.label;title=resolution.title;text=n.lastBattleOutcome==='defeat'?'전투에서 밀려나 거처 쪽으로 후퇴했다. 준비가 부족했다는 기억이 남는다.':n.lastBattleOutcome==='fled'?'싸움을 끝까지 이어가지 않고 퇴로를 확보했다.':n.lastBattleOutcome==='truce'?'전투 중 제안한 휴전이 받아들여졌다.':'상대를 물러서게 했다. 이 산의 대치는 아직 끝나지 않았다.';if(n.lastBattleOutcome==='defeat')applyEffects(n,{pressure:10,flags:['battle_defeat'],trust:-2});else applyEffects(n,{flags:['battle_'+n.lastBattleOutcome]});finishNode(n,resolution.choice,plots);n.story.battleContinuation=null;
 }else if(input.type==='rest'||input.type==='sleep'){if(n.pending.kind!=='menu')return{ok:false,state:s,error:'현재 사건을 해결하거나 서브 플롯 목록으로 돌아가세요.'};const p=n.characters[n.player];label=input.type==='rest'?'잠시 휴식한다':'밤을 보낸다';title='거처의 불빛';if(input.type==='sleep'){n.day++;n.todayActions=0;n.story.sleepCount++;p.hp=clamp(p.hp+35,0,p.maxHp);p.energy=p.maxEnergy;p.stability=clamp(p.stability+12);text=`밤을 보냈습니다 — ${n.day}일차 시작. 거처에서 기력을 되찾았다.`}else{p.hp=clamp(p.hp+8,0,p.maxHp);p.energy=clamp(p.energy+10,0,p.maxEnergy);text='잠시 숨을 고른다. 날짜는 그대로다.'}if(p.hp>p.maxHp*.6)p.status='건강';
 }else if(input.type==='choice'){const p=currentPlot(n,plots),node=currentNode(n,plots),c=node?.choices.find(c=>c.id===input.id);if(!c)return{ok:false,state:s,error:'이 장면에 없는 선택입니다.'};const denied=locks(n,c.requires);if(denied.length)return{ok:false,state:s,error:denied.join(' · ')};label=c.label;title=p.title===node.title?p.title:p.title+' · '+node.title;if(c.check)roll=check(n,c.check.stat,c.check.difficulty);const success=!roll||roll.success,branch=success?c:c.failure;if(!branch)return{ok:false,state:s,error:'판정 결과 데이터가 없습니다.'};applyEffects(n,branch.effects);text=branch.result||c.result;if(c.battle){n.combat={name:c.battle.name,id:null,hp:c.battle.hp,maxHp:c.battle.hp,power:c.battle.power,distance:1,round:1,guard:false,cover:false,intent:'공격',stunned:false};n.story.battleContinuation={choice:c,label,title,baseline:before,logStart};record(n,text,'story',7);n.story.revision++;n.pending=null;setupDecision(n,plots);return{ok:true,state:n,committed:false}}finishNode(n,c,plots);
 }else return{ok:false,state:s,error:'준비된 선택지 중 하나를 선택하세요.'};
 record(n,text,'story',7);if(roll)record(n,`${roll.result} · 주사위 ${roll.roll} / 성공 기준 ${roll.chance}`,'check',4,[]);
 n.tick++;if(n.day===dayBefore)n.todayActions++;const after=statsForDiff(n),changes=Object.keys(before).filter(k=>before[k]!==after[k]).map(k=>`${k} ${after[k]-before[k]>0?'+':''}${after[k]-before[k]}`);n.story.records.push({turn:n.tick,day:dayBefore,endDay:n.day,title,label,text,check:roll,changes,plot:s.story.active?.plot||null});n.story.revision++;n.pending=null;return{ok:true,state:n,committed:true};
}
export function restoreStory(raw,world,plots){if(!raw||![1,2,3].includes(raw.version)||!['jihyo','baekho'].includes(raw.player)||!Number.isInteger(raw.tick)||raw.tick<0)throw Error('지원하지 않는 저장 파일입니다.');if(raw.version<3){const n=newStory(world,raw.player,raw.seed);n.day=Number.isInteger(raw.day)?Math.max(1,raw.day):Math.floor(raw.tick/4)+1;n.tick=raw.tick;const old=raw.characters?.[raw.player];if(old)for(const k of ['hp','energy','power','agility','insight','will','stability','humanity','value'])if(Number.isFinite(old[k]))n.characters[n.player][k]=clamp(old[k],k==='hp'?1:0,k==='hp'?n.characters[n.player].maxHp:k==='energy'?60:100);n.legacyArchive=copy(raw);n.story.migratedFrom=raw.version;record(n,'이전 저장의 날짜·완료 턴·주인공 능력치를 이어받았다. 새 산속 플롯의 선택 이력은 처음부터 시작한다.','system',7,[]);return n}const n=copy(raw),ids=plots.subs.map(p=>p.id),mids=plots.mains.map(p=>p.id);if(n.location!=='forest'||!Number.isInteger(n.day)||n.day<1||!n.story||!Array.isArray(n.story.completed)||!Array.isArray(n.story.mainDone)||!Array.isArray(n.story.records)||!Array.isArray(n.story.flags)||!Array.isArray(n.log)||!Number.isFinite(n.rng)||!Number.isInteger(n.story.revision))throw Error('저장 구조가 손상되었습니다.');if(n.story.completed.some(x=>!ids.includes(x))||n.story.mainDone.some(x=>!mids.includes(x))||new Set(n.story.completed).size!==n.story.completed.length||n.story.ending&&!plots.endings[n.story.ending])throw Error('플롯 정보가 손상되었습니다.');for(const id of ['jihyo','baekho'])if(!n.characters?.[id]||!Number.isFinite(n.characters[id].hp)||!Number.isFinite(n.characters[id].energy))throw Error('캐릭터 정보가 손상되었습니다.');if(!Number.isFinite(n.story.pressure)||!Number.isInteger(n.todayActions)||!n.inventory||!Number.isFinite(n.inventory.herb)||!n.relations?.[companionId(n)+':'+n.player]||!Number.isFinite(trustValue(n))||!Array.isArray(n.visited)||n.visited.some(x=>x!=='forest')||!n.visited.includes('forest'))throw Error('상태 정보가 손상되었습니다.');if(n.story.active&&!currentNode(n,plots))throw Error('현재 장면이 존재하지 않습니다.');if(n.combat&&(!n.story.battleContinuation||!Number.isFinite(n.combat.hp)))throw Error('전투 저장이 손상되었습니다.');if(n.pending&&n.pending.id!==`${n.seed}-${n.story.revision}`)throw Error('대기 중인 선택이 손상되었습니다.');return n}
